<style>
.hero-world{position:relative;min-width:0;min-height:410px;overflow:hidden}.hero-world>.hero-art{position:absolute;inset:0;width:100%;height:100%}.kids .sheep-mascot{display:block;position:relative;border:0;padding:0;background:none;box-shadow:none;cursor:pointer;isolation:isolate;-webkit-tap-highlight-color:transparent;touch-action:manipulation}.sheep-mascot img{display:block;width:100%;height:100%;object-fit:contain;transform-origin:50% 91%;animation:sheep-idle 3.8s ease-in-out infinite;filter:drop-shadow(0 4px 3px #55344815);pointer-events:none}.sheep-shadow{position:absolute;left:25%;right:15%;height:8%;bottom:3%;background:#3c214335;filter:blur(5px);border-radius:50%;z-index:-1;animation:sheep-shadow 3.8s ease-in-out infinite}.kids .hero-sheep{position:absolute;width:54%;height:76%;right:3%;bottom:8%;z-index:2}.sheep-hello{position:absolute;top:-8px;left:50%;transform:translateX(-50%) translateY(5px);background:white;color:#54406f;border:1px solid #e5daef;border-radius:15px 15px 15px 3px;padding:8px 13px;box-shadow:0 4px 0 #4e337a19;white-space:nowrap;font:900 12px 'Nunito';opacity:0;transition:.2s;pointer-events:none}.sheep-mascot.hello .sheep-hello{opacity:1;transform:translateX(-50%) translateY(0)}.kids .mascot-motion{position:absolute;right:14px;bottom:12px;background:#fffE;border:1px solid #e1d8ef;color:#584574;border-radius:9px;font:800 10px 'Nunito';padding:7px 10px;z-index:3;cursor:pointer}.play-companion{height:77px;margin:10px auto -14px;display:flex;justify-content:center}.kids .companion-sheep{width:80px;height:83px}.win-companion{display:flex;justify-content:center;height:77px;margin:-10px 0 -14px}.kids .celebration-sheep{width:94px;height:96px;z-index:2}.win-companion+.win-art{height:59px;gap:105px}.win-companion+.win-art .win-spark{font-size:37px}.win-companion+.win-art .win-spark:nth-child(2){display:none}.sheep-mascot.cheer img{animation:sheep-hop 1.05s ease-in-out}.sheep-mascot.cheer .sheep-shadow{animation:sheep-hop-shadow 1.05s ease-in-out}@keyframes sheep-idle{0%,100%{transform:translateY(0) rotate(-1deg) scaleY(1)}50%{transform:translateY(-5px) rotate(1deg) scaleY(1.015)}}@keyframes sheep-shadow{0%,100%{opacity:.6;transform:scale(1)}50%{opacity:.4;transform:scale(.88)}}@keyframes sheep-hop{0%,100%{transform:translateY(0) rotate(0)}15%{transform:translateY(3px) scale(1.06,.92)}38%{transform:translateY(-24px) rotate(-7deg) scale(.97,1.03)}60%{transform:translateY(0) scale(1.07,.94)}80%{transform:translateY(-10px) rotate(5deg)}}@keyframes sheep-hop-shadow{0%,100%{opacity:.6;transform:scale(1)}38%{opacity:.2;transform:scale(.6)}80%{opacity:.3;transform:scale(.8)}}.mascot-still .sheep-mascot img,.mascot-still .sheep-shadow{animation:none!important;transform:none!important}.mascot-still .sheep-hello{transition:none}@media(max-width:650px){.hero-world{height:240px;min-height:0;grid-row:2}.kids .hero-sheep{height:87%;width:46%;bottom:3%;right:8%}.hero-world>.hero-art{height:100%}.play-companion{height:61px;margin:7px auto -12px}.kids .companion-sheep{width:65px;height:68px}.kids .tools{gap:6px}.kids .tools button{font-size:10px;padding:9px 11px}}@media(prefers-reduced-motion:reduce){.sheep-mascot img,.sheep-shadow{animation:none!important;transform:none!important}.sheep-hello{transition:none!important}}
</style>
<style>.kids .intro-block-art{width:108px;height:95px;margin:0 auto 21px;background:#eee7f9;border-radius:22px}.kids .intro-block-art .mini-blocks{transform:rotate(-10deg) scale(.8)}.kids .play-help{margin-top:19px;font-size:12px;color:#65557b}.kids .play-help summary{cursor:pointer;font-weight:800;min-height:30px;padding:5px}.kids .play-help p{font-size:12px;line-height:1.8;margin:9px 0;padding:10px;background:#f3eff9;border-radius:10px}.kids #introTitle{margin-top:8px}</style>
