@media(max-width:650px){.play-stage{display:flex;flex-direction:column-reverse;gap:7px;padding:0 13px 5px}.play-stage .boardarea{flex:1}.verse-panel{width:100%;flex-shrink:0;overflow:visible;max-height:none;padding:11px 13px;border-radius:14px}.kids-tetris .verse-panel .versestrip{font-size:15.5px;line-height:1.5;padding:8px 0}.verse-panel .read-heading{font-size:8px}.verse-panel .read-heading b{font-size:10px}.verse-footer{flex-direction:row;align-items:center;justify-content:space-between;gap:6px}.kids .verse-footer button{font-size:9px;padding:6px 8px}.kids-tetris .verse-panel .verse-progress{font-size:9px}.kids-tetris .verse-panel .mission-note{margin-top:8px;padding-top:7px;font-size:10px;line-height:1.4}.verse-panel .mission-note b{display:none}.kids-tetris .topbar{padding:8px 13px}.kids-tetris .infobar{padding:5px 15px;gap:5px 10px}.kids-tetris .save-row{min-height:12px;font-size:9px}.kids-tetris .cbtn{height:44px}.kids .verse-learning{padding:12px 14px;margin-top:16px}.kids .verse-learning>p{font-size:17px;line-height:1.5}.kids .mcard .icon{height:42px}.kids .mcard .icon svg{width:45px}}
</style>
<style>.puzzle-heading{display:flex;align-items:center;justify-content:center;gap:22px}.puzzle-title{text-align:left;min-width:0}.kids-play .puzzle-heading h1{font-size:clamp(25px,4vw,36px)}.puzzle-heading .play-companion{margin:0;height:82px;width:78px;flex-shrink:0}.kids-play .puzzle-heading .game-kicker{margin-bottom:6px}.kids-play .journey{margin-top:15px}@media(max-width:650px){.puzzle-heading{gap:12px}.puzzle-heading .play-companion{width:58px;height:67px}.kids-play .puzzle-heading h1{font-size:25px}.kids-play .puzzle-heading .ref{font-size:10px}.kids-play .puzzle-heading .game-kicker{font-size:9px}}</style>
