.word-builder{margin-top:14px;padding:12px;background:#241c32;border:1px solid #654e7b;border-radius:12px}.word-builder>span{font-size:9px;color:#d4bfe8;letter-spacing:.12em;font-weight:900}#letterSlots{display:flex;gap:4px;flex-wrap:wrap;margin-top:7px}.letter{display:grid;place-items:center;min-width:24px;height:29px;background:#51425f;color:#f6eafa;border:1px solid #816794;border-bottom:3px solid #191322;border-radius:5px;font:900 18px 'Nunito'}.letter.built{background:#ffe199;color:#413024;border-color:#edc66c}.kids-tetris .board{container-type:inline-size}.kids-tetris .board .tc{display:grid;place-items:center;font:900 clamp(10px,5.8cqw,22px)/1 'Nunito';color:#21172f;text-shadow:0 1px #ffffff55}.kids-tetris .board .tc.ghost{color:transparent;text-shadow:none}@media(max-width:650px){.word-builder{margin-top:8px;padding:7px 9px}.word-builder>span{font-size:8px}#letterSlots{gap:3px;margin-top:4px}.letter{min-width:20px;height:24px;font-size:16px}.kids-tetris .verse-panel .versestrip{font-size:15px;line-height:1.45;padding:8px 0}.kids-tetris .verse-panel .mission-note{margin-top:6px;padding-top:6px}}
